import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"59、【涣】 坎下巽上","description":"横渠易说 - 59、【涣】 坎下巽上","frontmatter":{"title":"59、【涣】 坎下巽上","description":"横渠易说 - 59、【涣】 坎下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/061.md","filePath":"zh/classics/hengqu/061.md"}'),l={name:"zh/classics/hengqu/061.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_59、【涣】-坎下巽上" tabindex="-1">59、【涣】 坎下巽上 <a class="header-anchor" href="#_59、【涣】-坎下巽上" aria-label="Permalink to “59、【涣】 坎下巽上”">​</a></h1><p>萃“王假有庙”，涣然后聚道乃久，故“王假有庙”互见于此。凡言“有庙”者，聚道之极也。</p><h3 id="彖曰-涣亨-刚来而不穷-柔得位乎外而上同。-王假有庙-王乃在中也-利涉大川-乘木有功也。" tabindex="-1">彖曰：涣亨，刚来而不穷，柔得位乎外而上同。“王假有庙”，王乃在中也；“利涉大川”，乘木有功也。 <a class="header-anchor" href="#彖曰-涣亨-刚来而不穷-柔得位乎外而上同。-王假有庙-王乃在中也-利涉大川-乘木有功也。" aria-label="Permalink to “彖曰：涣亨，刚来而不穷，柔得位乎外而上同。“王假有庙”，王乃在中也；“利涉大川”，乘木有功也。”">​</a></h3><h3 id="象曰-风行水上-涣-先王以享于帝立庙。" tabindex="-1">象曰：风行水上，涣，先王以享于帝立庙。 <a class="header-anchor" href="#象曰-风行水上-涣-先王以享于帝立庙。" aria-label="Permalink to “象曰：风行水上，涣，先王以享于帝立庙。”">​</a></h3><p>财散则民聚，王乃在涣中之一也。</p><h3 id="初六-用拯马壮-吉。-象曰-初六之吉-顺也。" tabindex="-1">初六，用拯马壮，吉。 象曰：初六之吉，顺也。 <a class="header-anchor" href="#初六-用拯马壮-吉。-象曰-初六之吉-顺也。" aria-label="Permalink to “初六，用拯马壮，吉。 象曰：初六之吉，顺也。”">​</a></h3><p>处险之下，故必用拯，无应于上，顺比九二之刚，拯而马壮，其吉宜也。</p><h3 id="九二-涣奔其杌-悔亡。-象曰-涣奔其杌-得愿也。" tabindex="-1">九二，涣奔其杌，悔亡。 象曰：“涣奔其杌”，得愿也。 <a class="header-anchor" href="#九二-涣奔其杌-悔亡。-象曰-涣奔其杌-得愿也。" aria-label="Permalink to “九二，涣奔其杌，悔亡。 象曰：“涣奔其杌”，得愿也。”">​</a></h3><p>奋于险中，进而之前，则难解悔亡，故曰“奔其杌”，三四皆险，故曰“得愿”，若退累于初，则险不能出，其悔终存。</p><h3 id="六三-涣其躬-无悔。-象曰-涣其躬-志在外也。" tabindex="-1">六三，涣其躬，无悔。 象曰：“涣其躬”，志在外也。 <a class="header-anchor" href="#六三-涣其躬-无悔。-象曰-涣其躬-志在外也。" aria-label="Permalink to “六三，涣其躬，无悔。 象曰：“涣其躬”，志在外也。”">​</a></h3><p>援上而进，惟求自脱于险，无悔而已，非能及物者也。</p><h3 id="六四-涣其群-元吉。涣有丘-匪夷所思。-象曰-涣其群元吉-光大也。" tabindex="-1">六四，涣其群，元吉。涣有丘，匪夷所思。 象曰：“涣其群元吉”，光大也。 <a class="header-anchor" href="#六四-涣其群-元吉。涣有丘-匪夷所思。-象曰-涣其群元吉-光大也。" aria-label="Permalink to “六四，涣其群，元吉。涣有丘，匪夷所思。 象曰：“涣其群元吉”，光大也。”">​</a></h3><p>己处险外，无私其应，常以拯众为心，则其志光大获吉；若志在所归之地，近累于五，则非能平均其虑者也。</p><h3 id="九五-涣汗其大号-涣王居-无咎。-象曰-王居无咎-正位也。" tabindex="-1">九五，涣汗其大号，涣王居，无咎。 象曰：“王居无咎”，正位也。 <a class="header-anchor" href="#九五-涣汗其大号-涣王居-无咎。-象曰-王居无咎-正位也。" aria-label="Permalink to “九五，涣汗其大号，涣王居，无咎。 象曰：“王居无咎”，正位也。”">​</a></h3><p>为涣之主，使物偏被其泽，正位凝命，可以免咎，不私于应，故能均布其大号也。涣然廓大，以王道自居乃无咎。</p><h3 id="上九-涣其血-去逖出-无咎。-象曰-涣其血-远害也。" tabindex="-1">上九，涣其血，去逖出，无咎。 象曰：“涣其血”，远害也。 <a class="header-anchor" href="#上九-涣其血-去逖出-无咎。-象曰-涣其血-远害也。" aria-label="Permalink to “上九，涣其血，去逖出，无咎。 象曰：“涣其血”，远害也。”">​</a></h3><p>乘刚在上，若系于三，害不可免，能绝弃阴类，远去其难，则可免咎。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
